<?php $stats=[];foreach(['mahasiswa','dosen','mata_kuliah','lokasi_kampus'] as $t){$stats[$t]=(int)$pdo->query("SELECT COUNT(*) FROM $t")->fetchColumn();}$st=$pdo->query("SELECT s.*,mk.nama_mk,k.nama_kelas,d.nama AS dosen FROM sesi_absensi s JOIN jadwal j ON j.id=s.jadwal_id JOIN mata_kuliah mk ON mk.id=j.mata_kuliah_id JOIN kelas k ON k.id=j.kelas_id JOIN dosen d ON d.id=j.dosen_id ORDER BY s.created_at DESC LIMIT 6");$rows=$st->fetchAll(); ?><div class="stats"><div class="stat"><small>Mahasiswa</small><strong><?=$stats['mahasiswa']?></strong><span>data aktif</span></div><div class="stat"><small>Dosen</small><strong><?=$stats['dosen']?></strong><span>pengajar</span></div><div class="stat"><small>Mata kuliah</small><strong><?=$stats['mata_kuliah']?></strong><span>terdaftar</span></div><div class="stat"><small>Lokasi</small><strong><?=$stats['lokasi_kampus']?></strong><span>titik validasi</span></div></div><section class="section" style="margin-top:20px"><div class="section-head"><h2>Sesi terbaru</h2><a class="btn btn-primary" href="lokasi.php">Kelola lokasi</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Mata kuliah</th><th>Dosen</th><th>Kelas</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['tanggal'])?></td><td><?=e($r['nama_mk'])?></td><td><?=e($r['dosen'])?></td><td><?=e($r['nama_kelas'])?></td><td><span class="badge green"><?=e($r['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></section>
</main></div><?php require __DIR__.'/../partials/footer.php'; ?>